 $$('[data-option]').forEach(b=>{if(x.answered){const o=x.options[Number(b.dataset.option)],right=type==='meaning'?current.options[0]:current.target;if(o===right)b.classList.add('correct');else if(o===x.selected)b.classList.add('incorrect');}b.onclick=()=>{x.selected=x.options[Number(b.dataset.option)];grade(x.selected===(type==='meaning'?current.options[0]:current.target));};});
 $$('[data-chunk]').forEach(b=>b.onclick=()=>{x.chosen.push(Number(b.dataset.chunk));renderExercise();});$$('[data-remove]').forEach(b=>b.onclick=()=>{x.chosen.splice(Number(b.dataset.remove),1);renderExercise();});if($('#check-build')){$('#check-build').onclick=()=>grade(x.chosen.map(id=>x.chunks[id]).join('')===x.sentence);$('#clear-build').onclick=()=>{x.chosen=[];renderExercise();};}
