function renderReview(){const entries=Object.entries(state.words),due=entries.filter(([,w])=>w.due<=Date.now());if(!reviewWord||!state.words[reviewWord])reviewWord=due[0]?.[0]||entries[0]?.[0];const word=reviewWord,w=state.words[word],d=all.find(d=>d.target===word)||all.find(d=>d.lines.some(s=>s.includes(word)));
 $('#workspace').innerHTML=`<div class="lesson-heading"><div><span class="chapter-label">YOUR PERSONAL WORD SHELF</span><h2 lang="zh-Hans">温故知新</h2><p>${entries.length} saved words · ${due.length} due now</p></div><button id="back-reading">Back to reading ↗</button></div>${!entries.length?'<div class="review-card empty"><h3>Save the words that slow you down.</h3><p>Switch on word help in a dialogue, tap a marked word, and save it here.</p></div>':`<article class="review-card"><span class="eyebrow">RECOGNISE THE WORD BEFORE REVEALING THE MEANING</span><div class="review-word" lang="zh-Hans">${word}</div><p class="context" lang="zh-Hans">${escapeHTML(d.lines.find(s=>s.includes(word)))}</p>${reviewReveal?`<p><strong>${escapeHTML(dictionary.get(word))}</strong></p><p class="hint">How easily did you recognise it?</p><div class="review-choices"><button id="review-again">Again · in 10 minutes</button><button id="review-good" class="primary">I knew it · ${[1,3,7,14][w.stage]} day${w.stage===0?'':'s'}</button></div>`:'<button id="reveal-word" class="primary">Reveal meaning</button>'}<div class="exercise-actions"><button id="open-context">Read the full dialogue</button><button id="remove-word">Remove from review</button></div><p class="hint">${w.due<=Date.now()?'Due now':'Next review: '+new Date(w.due).toLocaleDateString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}. Scheduling is a simple review aid, not a prediction of mastery.</p></article><div class="review-list">${entries.map(([term,item])=>`<button data-review="${term}"><strong lang="zh-Hans">${term}</strong><small>${item.due<=Date.now()?'Due now':'Scheduled'}</small></button>`).join('')}</div>`}`;
 $('#back-reading').onclick=()=>{mode='read';render();};if(!entries.length)return;$$('[data-review]').forEach(b=>b.onclick=()=>{reviewWord=b.dataset.review;reviewReveal=false;renderReview();});if($('#reveal-word'))$('#reveal-word').onclick=()=>{reviewReveal=true;renderReview();};if($('#review-good')){$('#review-good').onclick=()=>schedule(true);$('#review-again').onclick=()=>schedule(false);}$('#open-context').onclick=()=>choose(d.id);$('#remove-word').onclick=()=>{delete state.words[word];reviewWord=null;reviewReveal=false;save();renderReview();};}
function schedule(good){const w=state.words[reviewWord];w.due=Date.now()+(good?[1,3,7,14][w.stage]*86400000:600000);w.stage=good?Math.min(3,w.stage+1):0;reviewReveal=false;const due=Object.keys(state.words).filter(t=>state.words[t].due<=Date.now());reviewWord=due[0]||null;save();renderReview();toast(good?'Next review scheduled.':'Scheduled again in 10 minutes.');}
$('#search').oninput=renderLessons;$('#all-filter').onclick=()=>{classOnly=false;$('#all-filter').classList.add('selected');$('#class-filter').classList.remove('selected');renderLessons();};$('#class-filter').onclick=()=>{classOnly=true;$('#class-filter').classList.add('selected');$('#all-filter').classList.remove('selected');if(current.lesson<9)choose('9-1');else renderLessons();};$('#nav-read').onclick=()=>{mode='read';render();};$('#nav-review').onclick=()=>{mode='review';reviewReveal=false;reviewWord=null;render();};$('#nav-method').onclick=()=>$('#method').showModal();$('#method .close').onclick=()=>$('#method').close();
