$('#import-progress').onchange=async e=>{try{const raw=JSON.parse(await e.target.files[0].text());if(raw.version!==1||!raw.records||!raw.words)throw Error('format');const imported=cleanState(raw);for(const [id,r] of Object.entries(imported.records)){const old=state.records[id];if(old){r.reads=Math.max(r.reads,old.reads);for(const t of ['meaning','cloze','build'])r.passed[t]=r.passed[t]||old.passed[t];}state.records[id]=r;}Object.assign(state.words,imported.words);save();render();toast('Progress imported and merged.');}catch{toast('Could not import that file. Choose an exported reading-progress JSON.');}e.target.value='';};render();
